def connect_rule(src, dot, bg, color=2, maxdist=7):
 o=[row[:] for row in src]; R=len(src); C=len(src[0])
 for r in range(R):
  points=[c for c,v in enumerate(src[r]) if v==dot]
  for a,b in zip(points,points[1:]):
   if b-a<=maxdist and all(src[r][c]==bg for c in range(a+1,b)):
    for c in range(a+1,b):o[r][c]=color
 for c in range(C):
  points=[r for r in range(R) if src[r][c]==dot]
  for a,b in zip(points,points[1:]):
   if b-a<=maxdist and all(src[r][c]==bg for r in range(a+1,b)):
    for r in range(a+1,b):o[r][c]=color
 return o
