def comps(src,v):
 R,C=len(src),len(src[0]); seen=set(); out=[]
 for r in range(R):
  for c in range(C):
   if src[r][c]==v and (r,c) not in seen:
    st=[(r,c)]; seen.add((r,c)); comp=[]
    while st:
     x=st.pop(); comp.append(x)
     for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
      y=(x[0]+dr,x[1]+dc)
      if 0<=y[0]<R and 0<=y[1]<C and src[y[0]][y[1]]==v and y not in seen:
       seen.add(y);st.append(y)
    out.append(comp)
 return out
